/**
 * Jinx Legion + Magician: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Legion
 * Wiki: https://wiki.bloodontheclocktower.com/Magician
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L117). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { alignmentOf } from '#lib/core/model/selectors.ts';
import { demonInfo } from '#lib/core/rules/evil-info.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './legion.test-support.ts';

describe('Legion + Magician jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'legion', 'magician');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('legion')?.name).toBe('Legion');
		expect(data.byId.get('magician')?.name).toBe('Magician');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['legion', 'magician'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['legion'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['magician'])).not.toContain(jinx);
	});

	describe('Legion wake in groups and learn who is good, but not the Magician', () => {
		const script = scriptOf(['legion', 'magician', 'imp', 'chef', 'empath', 'monk', 'poisoner']);
		const base = scenario(['legion', 'legion', 'legion', 'legion', 'magician', 'chef', 'empath'], {
			script
		});

		it("is data in the Magician's rules", () => {
			expect(jinxRulesBetween('legion', 'magician')).toEqual({ demonLearnsGood: true });
		});

		it('shows the good players at Demon info, never the Magician', () => {
			// Wiki: "If the Magician is in play, during the Demon info step, Legion wake in separate
			// groups. Each group learns which players are good, but does not learn the Magician."
			const info = demonInfo(base.game, base.characters);
			expect(alignmentOf(base.game, base.seat('magician'))).toBe('good');
			expect(info.goodShown).toEqual({
				seats: [base.seat('chef'), base.seat('empath')],
				hiddenBy: 'magician'
			});
			expect(info.shownAsMinions).toEqual([]);
		});

		it('leaves Demon info as usual with another Demon', () => {
			// Wiki: "If the Magician is in play, during the Demon info step, Legion wake in separate
			// groups."
			const s = scenario(['imp', 'poisoner', 'magician', 'chef', 'empath', 'monk', 'legion'], {
				script
			}).becomes(6, 'monk', 'good');
			const info = demonInfo(s.game, s.characters);
			expect(info.goodShown).toBeUndefined();
			expect(info.shownAsMinions).toEqual([s.seat('magician')]);
		});
	});
});
